function minMaxScore(vals,v,{inverse=false}={}){const a=vals.filter(x=>Number.isFinite(x));if(!a.length||!Number.isFinite(v))return null;const lo=Math.min(...a),hi=Math.max(...a);if(Math.abs(hi-lo)<1e-9)return 100;let s=(v-lo)/(hi-lo)*100;if(inverse)s=100-s;return clamp(s,0,100)}
function weighted(parts){let sum=0,w=0;for(const [v,weight] of parts){if(v==null||!Number.isFinite(v))continue;sum+=v*weight;w+=weight}return w?sum/w:null}
function scoreClass(v){return v==null?'':v>=70?'high':v>=45?'mid':'low'}

function rosterIntersectionNames(){const board=new Set(state.boardRoster.map(r=>r.date+'|'+idKey(r.server))),tip=new Set(state.tipRoster.map(r=>r.date+'|'+idKey(r.server))),names=new Set();for(const k of board){if(tip.has(k))names.add(k.split('|').slice(1).join('|'))}return names}
function buildRows(){
 const map=new Map(),get=(n,meta={})=>{n=canonical(n);if(!map.has(n))map.set(n,{name:n,active:isActiveName(n),events:[],reports:[],tables:0,guests:0,rotation:0,hours:0,sales:0,paidTip:0,cashTip:0,tipIncome:0,payout:0,busser:0,barOut:0,barIn:0,days:new Set(),am:0,pm:0,sources:new Set(),aliases:new Set(),scheduled:false});const x=map.get(n);if(meta.source)x.sources.add(meta.source);if(meta.raw)x.aliases.add(meta.raw);if(meta.scheduled)x.scheduled=true;if(meta.date)x.days.add(meta.date);return x};
 const rosterBoth=rosterIntersectionNames();
 /* No-activity roster rows only appear when Board AND Tip currently agree. This prevents deleted Mia/stale draft resurrection. */
 for(const r of state.boardRoster){if(rosterBoth.has(idKey(r.server)))get(r.server,{source:r.source,raw:r.rawServer,scheduled:true,date:r.date})}
 for(const r of state.tipRoster){if(rosterBoth.has(idKey(r.server)))get(r.server,{source:r.source,raw:r.rawServer,scheduled:true,date:r.date})}
 for(const e of state.board){const x=get(e.server,{source:'BOARD',raw:e.rawServer,date:e.date});x.events.push(e);x.tables++;x.guests+=num(e.people);x.rotation+=num(e.rotationSlots);x.days.add(e.date);if(e.shift==='AM')x.am++;if(e.shift==='PM')x.pm++}
 const boardIds=new Set([...state.board.map(e=>e.server),...state.boardRoster.map(r=>r.server)]);
 for(const r of state.tips){const n=reportName(r);if(!n)continue;const c=canonical(n),pos=reportPosition(r);if(pos&&!/server/i.test(pos))continue;if(!pos&&!boardIds.has(c))continue;const bucket=shiftBucket(r);if(state.shift!=='ALL'&&bucket!=='ALL'&&bucket!==state.shift)continue;if(state.shift!=='ALL'&&bucket==='ALL')continue;const x=get(c,{source:'TIP REPORT',raw:n,date:r.date});x.reports.push(r);x.days.add(r.date);x.hours+=reportHours(r);x.sales+=reportSales(r);x.paidTip+=num(r.paidTip);x.cashTip+=num(r.cashTip);x.tipIncome+=reportTip(r);x.payout+=reportPayout(r);x.busser+=reportBusser(r);x.barOut+=reportBarOut(r);x.barIn+=reportBarIn(r)}
 let rows=[...map.values()];
 rows.forEach(x=>{x.daysCount=x.days.size;x.avgParty=x.tables?x.guests/x.tables:0;x.salesPerGuest=x.guests?x.sales/x.guests:0;x.salesPerTable=x.tables?x.sales/x.tables:0;x.tablesPerHour=x.hours?x.tables/x.hours:0;x.guestsPerHour=x.hours?x.guests/x.hours:0;x.salesPerHour=x.hours?x.sales/x.hours:0;x.tipPerHour=x.hours?x.tipIncome/x.hours:0;x.tipPerGuest=x.guests?x.tipIncome/x.guests:0;x.rotationPerHour=x.hours?x.rotation/x.hours:0;x.guestsPerRotation=x.rotation?x.guests/x.rotation:0;x.tablesPerRotation=x.rotation?x.tables/x.rotation:0;x.medianSeatGap=medianGap(x.events);x.hasBoardActivity=!!(x.tables||x.guests);x.hasTipReport=x.reports.length>0;x.dataComplete=!!(x.hasBoardActivity&&x.hasTipReport&&x.hours>0&&x.sales>0);x.dataQuality=(x.hasBoardActivity?50:0)+(x.hasTipReport&&x.hours>0?25:0)+(x.hasTipReport&&x.sales>0?25:0);x.hasPerformance=x.hasBoardActivity||x.hasTipReport});
 const eligible=rows.filter(x=>x.dataComplete);
 const vals=k=>eligible.map(r=>r[k]);
 for(const x of rows){if(!x.dataComplete){x.paceScore=x.salesScore=x.tipScore=x.overall=null;continue}const gapScore=x.medianSeatGap?minMaxScore(vals('medianSeatGap'),x.medianSeatGap,{inverse:true}):null;x.paceScore=weighted([[minMaxScore(vals('tablesPerHour'),x.tablesPerHour),.45],[minMaxScore(vals('guestsPerHour'),x.guestsPerHour),.35],[gapScore,.20]]);x.salesScore=weighted([[minMaxScore(vals('salesPerHour'),x.salesPerHour),.50],[minMaxScore(vals('salesPerGuest'),x.salesPerGuest),.30],[minMaxScore(vals('salesPerTable'),x.salesPerTable),.20]]);x.tipScore=weighted([[minMaxScore(vals('tipPerHour'),x.tipPerHour),.65],[minMaxScore(vals('tipPerGuest'),x.tipPerGuest),.35]]);x.overall=weighted([[x.paceScore,.40],[x.salesScore,.40],[x.tipScore,.20]])}
 const totalGuests=rows.reduce((a,x)=>a+x.guests,0),totalRotation=rows.reduce((a,x)=>a+x.rotation,0);for(const x of rows){x.guestShare=totalGuests?x.guests/totalGuests:0;x.rotationShare=totalRotation?x.rotation/totalRotation:0;x.rotationDeltaPct=(x.guestShare-x.rotationShare)*100}
 rows=rows.filter(x=>x.hasPerformance||x.scheduled).sort((a,b)=>(b.dataComplete-a.dataComplete)||num(b.overall)-num(a.overall)||b.sales-a.sales||b.guests-a.guests||a.name.localeCompare(b.name));
 return rows
}
function totals(rows){return rows.reduce((a,x)=>{a.tables+=x.tables;a.guests+=x.guests;a.rotation+=x.rotation;a.hours+=x.hours;a.sales+=x.sales;a.tip+=x.tipIncome;a.payout+=x.payout;return a},{tables:0,guests:0,rotation:0,hours:0,sales:0,tip:0,payout:0})}
function groupFairness(rows){const active=rows.filter(x=>x.rotation>0||x.guests>0),tr=active.reduce((a,x)=>a+x.rotation,0),tg=active.reduce((a,x)=>a+x.guests,0);if(!tr||!tg)return null;const tv=.5*active.reduce((a,x)=>a+Math.abs(x.rotation/tr-x.guests/tg),0);return clamp((1-tv)*100,0,100)}
function peerMedian(rows,key){return median(rows.filter(x=>x.dataComplete).map(x=>x[key]))}
function diagnose(row,rows,lang='EN'){
 const id=lang==='ID',causes=[],actions=[];
 if(!row.dataComplete){return {status:id?'DATA BELUM LENGKAP':'DATA NOT READY',causes:[id?'Data dari Board dan Tip belum lengkap, jadi server ini belum aman untuk dibandingkan.':'Board and Tip data are not complete yet, so this server should not be compared yet.'],actions:[id?'Lengkapi laporan Tip/jam kerja dan pastikan data meja dari Board sudah masuk.':'Finish the Tip/work-hours report and make sure the Board table data is synced first.']}}
 const m={tph:peerMedian(rows,'tablesPerHour'),gph:peerMedian(rows,'guestsPerHour'),gap:peerMedian(rows,'medianSeatGap'),sph:peerMedian(rows,'salesPerHour'),spg:peerMedian(rows,'salesPerGuest'),spt:peerMedian(rows,'salesPerTable'),tiph:peerMedian(rows,'tipPerHour'),rph:peerMedian(rows,'rotationPerHour')};
 if(row.paceScore<45){if(row.tablesPerHour<m.tph*.88)causes.push(id?'Server ini menerima meja lebih sedikit per jam dibanding server lain yang datanya lengkap.':'This server handled fewer tables per hour than the other servers with complete data.');if(row.guestsPerHour<m.gph*.88)causes.push(id?'Server ini melayani customer lebih sedikit per jam dibanding server lain yang datanya lengkap.':'This server served fewer customers per hour than the other servers with complete data.');if(row.medianSeatGap&&m.gap&&row.medianSeatGap>m.gap*1.18)causes.push(id?'Jarak waktu dari satu meja baru ke meja berikutnya lebih lama dari biasanya di tim.':'The time between one new table and the next was longer than usual for the team.');actions.push(id?'Cek dulu apakah section, meja kosong, skip, atau ukuran rombongan membuat kesempatan server ini lebih sedikit. Kalau kesempatan sama, baru coaching soal kesiapan meja, kecepatan ambil order, dan komunikasi dengan host.':'First check whether section, open-table availability, skips, or party size gave this server fewer opportunities. If the opportunities were similar, then coach table readiness, order-taking speed, and communication with the host.')}
 if(row.salesScore<45){if(row.salesPerGuest<m.spg*.9){causes.push(id?'Rata-rata belanja per customer lebih rendah dibanding server lain yang datanya lengkap.':'Average spending per customer was lower than the other servers with complete data.');actions.push(id?'Latih cara menawarkan minuman, appetizer, add-on, combo upgrade, dan dessert secara natural tanpa memaksa customer.':'Coach natural suggestions for drinks, appetizers, add-ons, combo upgrades, and dessert without pressuring customers.')}if(row.salesPerHour<m.sph*.88&&row.salesPerGuest>=m.spg*.9){causes.push(id?'Penjualan per jam rendah, tetapi belanja per customer masih normal. Kemungkinan masalahnya jumlah meja/customer yang didapat, bukan cara menawarkan menu.':'Sales per hour were low, but spending per customer was still normal. The likely issue is the number of tables/customers received, not menu selling.');actions.push(id?'Cek pembagian meja, section, dan jumlah giliran sebelum memberi coaching penjualan.':'Check table distribution, section, and number of turns before giving sales coaching.')}}
 if(row.tipScore<45){causes.push(id?'Tip yang diterima per jam/customer lebih rendah dibanding server lain yang datanya lengkap.':'Tips earned per hour/customer were lower than the other servers with complete data.');actions.push(id?'Jangan langsung anggap servicenya buruk. Cek input cash tip, ukuran rombongan, complaint/feedback, dan kualitas service dulu.':'Do not immediately assume the service was poor. First check cash-tip entry, party size, complaints/feedback, and service quality.')}
 if(m.rph&&row.rotationPerHour<m.rph*.78){causes.push(id?'Server ini mendapat giliran meja per jam lebih sedikit dari biasanya di tim.':'This server received fewer table turns per hour than usual for the team.');actions.push(id?'Cek pembagian section dan riwayat skip. Jangan menilai server buruk hanya karena kesempatan mejanya lebih sedikit.':'Check section assignment and skip history. Do not rate a server poorly just because they received fewer table opportunities.')}
 if(!causes.length)causes.push(id?'Tidak ada masalah utama yang terlihat dari data lengkap pada periode ini.':'No major problem stands out from the complete data for this period.');
 if(!actions.length)actions.push(id?'Pertahankan pola kerja sekarang dan cek lagi konsistensinya dalam periode yang lebih panjang.':'Keep the current work pattern and check consistency again over a longer period.');
 const status=row.overall>=70?(id?'KUAT':'STRONG'):row.overall>=45?(id?'PERLU DIPANTAU':'WATCH'):(id?'PERLU COACHING':'NEEDS COACHING');return {status,causes:[...new Set(causes)],actions:[...new Set(actions)]}
}
function analyze(rows){const complete=rows.filter(x=>x.dataComplete).sort((a,b)=>b.overall-a.overall),strongest=complete[0]||null,weakest=complete.length>1?complete.at(-1):null,fastest=[...complete].sort((a,b)=>b.paceScore-a.paceScore)[0]||null,slowest=complete.length>1?[...complete].sort((a,b)=>a.paceScore-b.paceScore)[0]:null,bestSales=[...complete].sort((a,b)=>b.salesScore-a.salesScore)[0]||null,lowestSales=complete.length>1?[...complete].sort((a,b)=>a.salesScore-b.salesScore)[0]:null,incomplete=rows.filter(x=>x.hasPerformance&&!x.dataComplete),fairness=groupFairness(rows);return {complete,strongest,weakest,fastest,slowest,bestSales,lowestSales,incomplete,fairness}}
function rebuild(){state.rows=buildRows();state.analysis=analyze(state.rows);state.rawNames=[...new Set([...state.board.map(e=>e.rawServer),...state.boardRoster.map(r=>r.rawServer),...state.tipRoster.map(r=>r.rawServer),...state.tips.map(r=>reportName(r)).filter(Boolean)])].filter(Boolean).sort();$('updatedAt').textContent=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});renderKpis();renderContent()}

function renderKpis(){const t=totals(state.rows),complete=state.analysis?.complete?.length||0;$('kpis').innerHTML=[['Tables Served',t.tables,'from Quick Board'],['Customers',t.guests,t.tables?n1(t.guests/t.tables)+' customers / table':'—'],['Total Sales',money(t.sales),t.guests?money(t.sales/t.guests)+' / customer':'—'],['Work Hours',n1(t.hours),complete+' server(s) ready to compare'],['Tips Earned',money(t.tip),t.hours?money(t.tip/t.hours)+' / work hour':'—'],['Fair Table Distribution',state.analysis?.fairness==null?'—':Math.round(state.analysis.fairness)+'%',state.analysis?.incomplete?.length?state.analysis.incomplete.length+' server(s) still missing data':'all comparison data ready']].map(x=>`<div class="kpi"><span>${x[0]}</span><b>${x[1]}</b><small>${x[2]}</small></div>`).join('')}
function scoreCell(x,key){const v=x[key];return v==null?'—':`<span class="score ${scoreClass(v)}">${Math.round(v)}</span>`}
function rowTable(rows=state.rows){let rank=0;return `<div class="tablewrap"><table><thead><tr><th>Server</th><th>Overall Score</th><th>Work Speed</th><th>Sales Result</th><th>Tip Result</th><th>Data Status</th><th>Work Hours</th><th>Tables</th><th>Customers</th><th>Table Turns</th><th>Sales</th><th>Tips</th><th>Sales / Hr</th><th>Customers / Hr</th><th>Tables / Hr</th><th>Sales / Customer</th><th>Time Between Tables</th></tr></thead><tbody>${rows.map(x=>{const rn=x.dataComplete?++rank:'—';return `<tr class="clickrow" data-server="${esc(x.name)}"><td><span class="rank">${rn}</span><b>${esc(x.name)}</b>${x.active?'':' <span class="tag">INACTIVE</span>'}${!x.hasPerformance?' <span class="tag">ROSTER</span>':''}</td><td>${scoreCell(x,'overall')}</td><td>${scoreCell(x,'paceScore')}</td><td>${scoreCell(x,'salesScore')}</td><td>${scoreCell(x,'tipScore')}</td><td><span class="badge ${x.dataComplete?'strong':x.hasPerformance?'warn':'neutral'}">${x.dataComplete?'READY':x.hasPerformance?'MISSING DATA':'ROSTER'}</span></td><td>${n1(x.hours)}</td><td>${x.tables}</td><td>${x.guests}</td><td>${x.rotation}</td><td>${money(x.sales)}</td><td>${money(x.tipIncome)}</td><td>${x.hours?money(x.salesPerHour):'—'}</td><td>${x.hours?n1(x.guestsPerHour):'—'}</td><td>${x.hours?n1(x.tablesPerHour):'—'}</td><td>${x.guests?money(x.salesPerGuest):'—'}</td><td>${x.medianSeatGap?n1(x.medianSeatGap)+' min':'—'}</td></tr>`}).join('')}</tbody></table></div>`}
function bars(title,rows,key,format=v=>n1(v),eligibleFn=x=>x.dataComplete){const a=[...rows.filter(eligibleFn)].sort((x,y)=>num(y[key])-num(x[key])).slice(0,8),mx=Math.max(1,...a.map(x=>num(x[key])));return `<div class="card"><div class="section-title"><h2>${title}</h2><small>${a.length?'Showing '+a.length:'Waiting for complete data'}</small></div>${a.map((x,i)=>`<div class="barrow"><span>${i+1}. ${esc(x.name)}</span><div class="bartrack"><i style="width:${Math.max(3,num(x[key])/mx*100)}%"></i></div><b>${format(x[key])}</b></div>`).join('')||'<p class="muted">This comparison will appear after Board + final Tip/work-hour data are complete.</p>'}</div>`}
function executiveHTML(){const a=state.analysis,weak=a.weakest,weakD=weak?diagnose(weak,state.rows,'EN'):null;return `<div class="recommend" style="margin-bottom:16px"><b>How to read the scores:</b> 100 = highest result among servers with complete data for the selected period. 0 = lowest result in that group. It does <b>not</b> mean “perfect” or “bad”. Always read the explanation and table-distribution context before coaching.</div><div class="summaryGrid"><div class="card heroInsight"><span class="badge strong">BEST PERFORMANCE • COMPLETE DATA</span><div class="bigName">${a.strongest?esc(a.strongest.name):'Waiting for complete data'}</div><p>${a.strongest?`Overall Score ${Math.round(a.strongest.overall)} • Work Speed ${Math.round(a.strongest.paceScore)} • Sales Result ${Math.round(a.strongest.salesScore)} • Tip Result ${Math.round(a.strongest.tipScore)}`:'Comparison appears only after Board activity and final Tip/work-hour data are both available.'}</p><div class="dimensionGrid" style="margin-top:16px"><div class="dim"><span>Fastest Work Speed</span><b>${a.fastest?esc(a.fastest.name):'—'}</b><small>${a.fastest?Math.round(a.fastest.paceScore)+'/100':'—'}</small></div><div class="dim"><span>Best Sales Result</span><b>${a.bestSales?esc(a.bestSales.name):'—'}</b><small>${a.bestSales?Math.round(a.bestSales.salesScore)+'/100':'—'}</small></div><div class="dim"><span>Fair Table Distribution</span><b>${a.fairness==null?'—':Math.round(a.fairness)+'%'}</b><small>how evenly opportunities matched customer load</small></div><div class="dim"><span>Ready to Compare</span><b>${a.complete.length}</b><small>${a.incomplete.length} still missing data</small></div></div></div><div class="card heroInsight"><span class="badge weak">NEEDS MOST IMPROVEMENT</span><div class="bigName">${weak?esc(weak.name):'Not enough servers to compare'}</div>${weak?`<p><b>Overall Score ${Math.round(weak.overall)}/100</b> • Work Speed ${Math.round(weak.paceScore)} • Sales Result ${Math.round(weak.salesScore)} • Tip Result ${Math.round(weak.tipScore)}</p><div class="insightList">${weakD.causes.slice(0,3).map(x=>`<div class="insight"><b>What we found</b><span>${esc(x)}</span></div>`).join('')}</div><div class="recommend" style="margin-top:11px"><b>What to do:</b> ${esc(weakD.actions[0])}</div>`:`<p>At least two servers need complete Board + Tip data before the app can identify who needs the most improvement.</p>`}</div></div><div class="grid2" style="margin-top:14px">${bars('Overall Score',state.rows,'overall',v=>Math.round(v))}${bars('Work Speed',state.rows,'paceScore',v=>Math.round(v))}</div><div class="card" style="margin-top:14px"><div class="section-title"><h2>Server Summary</h2><small>${state.from} → ${state.to}</small></div>${rowTable()}</div><div class="recommend" style="margin-top:14px"><b>Simple formula:</b> Overall Score = 40% Work Speed + 40% Sales Result + 20% Tip Result. Table distribution is checked as context so a server is not blamed just because they received fewer opportunities. Servers with missing Board or final Tip/work-hour data are not scored.</div>`}
function renderContent(){const c=$('content'),r=state.rows;if(state.tab==='overview')c.innerHTML=executiveHTML();else if(state.tab==='ranking')c.innerHTML=`<div class="grid2">${bars('Overall Score',r,'overall',v=>Math.round(v))}${bars('Fastest Work Speed',r,'paceScore',v=>Math.round(v))}${bars('Best Sales Result',r,'salesScore',v=>Math.round(v))}${bars('Best Tip Result',r,'tipScore',v=>Math.round(v))}</div><div class="card" style="margin-top:14px">${rowTable()}</div>`;else if(state.tab==='rotation')c.innerHTML=rotationHTML();else if(state.tab==='finance')c.innerHTML=`<div class="grid2">${bars('Sales per Work Hour',r,'salesPerHour',money)}${bars('Average Sales per Customer',r,'salesPerGuest',money)}${bars('Tips per Work Hour',r,'tipPerHour',money)}${bars('Customers per Work Hour',r,'guestsPerHour',n1)}</div><div class="card" style="margin-top:14px">${rowTable([...r].sort((a,b)=>b.salesPerHour-a.salesPerHour))}</div>`;else renderTables(c);bindRows()}
function rotationHTML(){const a=state.analysis;return `<div class="summaryGrid"><div class="card heroInsight"><span class="badge info">TABLE DISTRIBUTION</span><div class="bigName">${a.fairness==null?'—':Math.round(a.fairness)+'% evenly distributed'}</div><p>This compares each server's share of table turns with the share of customers they actually received. It helps the manager see whether the floor gave similar opportunities.</p></div><div class="card heroInsight"><span class="badge ${a.slowest?'warn':'neutral'}">WORK SPEED WATCH</span><div class="bigName">${a.slowest?esc(a.slowest.name):'Waiting for data'}</div><p>${a.slowest?`Lowest work-speed score among complete data: ${Math.round(a.slowest.paceScore)}/100. Check table opportunities first before coaching the server.`:'At least two servers with complete data are needed.'}</p></div></div><div class="grid2" style="margin-top:14px">${bars('Table Turns per Work Hour',state.rows,'rotationPerHour',n1)}${bars('Customers Received per Table Turn',state.rows,'guestsPerRotation',n1,x=>x.hasBoardActivity)}</div><div class="card" style="margin-top:14px"><div class="section-title"><h2>Table Distribution & Work Speed</h2><small>“Time Between Tables” means the gap between new seating events. It is not the time needed to finish serving a table.</small></div>${rowTable([...state.rows].sort((a,b)=>num(b.rotationPerHour)-num(a.rotationPerHour)))}</div>`}
function renderTables(c){const map=new Map();state.board.forEach(e=>{if(!map.has(e.table))map.set(e.table,{table:e.table,seatings:0,guests:0,servers:new Map()});const x=map.get(e.table);x.seatings++;x.guests+=e.people;x.servers.set(e.server,(x.servers.get(e.server)||0)+1)});const a=[...map.values()].sort((x,y)=>y.seatings-x.seatings);c.innerHTML=`<div class="card"><div class="section-title"><h2>Table Utilization</h2><small>Selected period</small></div><div class="tablewrap"><table><thead><tr><th>Table</th><th>Seatings</th><th>Guests</th><th>Avg Party</th><th>Most Frequent Server</th></tr></thead><tbody>${a.map(x=>{const top=[...x.servers].sort((p,q)=>q[1]-p[1])[0];return `<tr><td><b>${esc(x.table)}</b></td><td>${x.seatings}</td><td>${x.guests}</td><td>${n1(x.guests/x.seatings)}</td><td>${top?esc(top[0])+' ('+top[1]+')':'—'}</td></tr>`}).join('')}</tbody></table></div></div>`}
function bindRows(){document.querySelectorAll('[data-server]').forEach(tr=>tr.onclick=()=>openServer(tr.dataset.server))}
function openServer(name){const x=state.rows.find(r=>r.name===name);if(!x)return;const d=diagnose(x,state.rows,'EN'),events=[...x.events].sort((a,b)=>(a.date+a.shift).localeCompare(b.date+b.shift)||a.seatedAt-b.seatedAt);$('modalTitle').textContent=name+' • Easy Performance Review';$('modalBody').innerHTML=`<div class="dimensionGrid"><div class="dim"><span>Overall Score</span><b>${x.overall==null?'N/A':Math.round(x.overall)}</b><small>${d.status}</small></div><div class="dim"><span>Work Speed</span><b>${x.paceScore==null?'—':Math.round(x.paceScore)}</b><small>${n1(x.tablesPerHour)} tables / work hour</small></div><div class="dim"><span>Sales Result</span><b>${x.salesScore==null?'—':Math.round(x.salesScore)}</b><small>${money(x.salesPerHour)} / work hour</small></div><div class="dim"><span>Tip Result</span><b>${x.tipScore==null?'—':Math.round(x.tipScore)}</b><small>${money(x.tipPerHour)} / work hour</small></div></div><div class="summaryGrid" style="margin-top:14px"><div class="card"><h2>What We Found</h2><div class="insightList">${d.causes.map((v,i)=>`<div class="insight"><b>${i+1}. Finding</b><span>${esc(v)}</span></div>`).join('')}</div></div><div class="card"><h2>What the Manager Can Do</h2><div class="insightList">${d.actions.map((v,i)=>`<div class="insight"><b>${i+1}. Action</b><span>${esc(v)}</span></div>`).join('')}</div></div></div><div class="card" style="margin-top:14px"><div class="section-title"><h2>Work & Money Details</h2><small>${[...x.aliases].map(esc).join(' • ')||esc(x.name)}</small></div><div class="dimensionGrid"><div class="dim"><span>Tables / Customers</span><b>${x.tables} / ${x.guests}</b><small>${n1(x.avgParty)} customers / table</small></div><div class="dim"><span>Table Turns</span><b>${x.rotation}</b><small>${n1(x.rotationPerHour)} / work hour</small></div><div class="dim"><span>Total Sales</span><b>${money(x.sales)}</b><small>${money(x.salesPerGuest)} / customer</small></div><div class="dim"><span>Tips Earned</span><b>${money(x.tipIncome)}</b><small>${money(x.tipPerGuest)} / customer</small></div></div></div><div class="card" style="margin-top:14px"><h2>Table History</h2><div class="tablewrap" style="margin-top:10px"><table><thead><tr><th>Date</th><th>Shift</th><th>Time</th><th>Table</th><th>Customers</th><th>Section</th><th>Table Turns</th><th>Source</th></tr></thead><tbody>${events.map(e=>`<tr><td>${e.date}</td><td>${e.shift}</td><td>${e.seatedAt?new Date(e.seatedAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):'—'}</td><td>${esc(e.table)}</td><td>${e.people}</td><td>${esc(e.section)}</td><td>${e.rotationSlots}</td><td>${e.source}</td></tr>`).join('')}</tbody></table></div></div>`;$('modal').classList.remove('hidden')}
function identityModal(){const groups=new Map();state.rawNames.forEach(n=>{const c=canonical(n);if(!groups.has(c))groups.set(c,[]);groups.get(c).push(n)});$('modalTitle').textContent='Employee Identity Sync';$('modalBody').innerHTML=`<p class="muted">Merge different Board/Tip names into one analytics identity. Source apps are never rewritten.</p><div class="aliasgrid">${[...groups].sort().map(([c,aliases])=>`<div class="aliasitem"><div><b>${esc(c)}</b><div class="muted">${aliases.map(esc).join(' • ')}</div></div><span class="tag">${isActiveName(c)?'ACTIVE':'INACTIVE'}</span></div>`).join('')}</div><div class="card" style="margin-top:14px"><h2>Merge / Rename</h2><div class="grid2" style="margin-top:12px"><div class="field"><label>Source name / alias</label><select id="aliasSource">${state.rawNames.map(n=>`<option>${esc(n)}</option>`).join('')}</select></div><div class="field"><label>Canonical employee name</label><input id="aliasCanonical" placeholder="Example: Ariana Garner"></div></div><div style="display:flex;gap:8px;margin-top:12px;flex-wrap:wrap"><button class="btn primary" id="mergeAlias">Save Alias</button><button class="btn" id="toggleInactive">Toggle Active / Inactive</button><button class="btn red" id="resetAliases">Reset Defaults</button></div></div>`;$('modal').classList.remove('hidden');$('mergeAlias').onclick=()=>{const s=$('aliasSource').value,c=normName($('aliasCanonical').value);if(!s||!c)return alert('Choose source name and canonical name.');identity[idKey(s)]={canonical:c,active:identity[idKey(s)]?.active!==false};identity[idKey(c)]={canonical:c,active:identity[idKey(c)]?.active!==false};saveIdentity();refreshBoard();identityModal()};$('toggleInactive').onclick=()=>{const s=$('aliasSource').value,c=canonical(s),active=isActiveName(c);Object.keys(identity).forEach(k=>{if(identity[k].canonical===c)identity[k].active=!active});identity[idKey(c)]={canonical:c,active:!active};saveIdentity();rebuild();identityModal()};$('resetAliases').onclick=()=>{if(confirm('Reset identity aliases to app defaults?')){localStorage.removeItem('fzsi_identity_v12');localStorage.removeItem('fzsi_identity_v11');localStorage.removeItem('fzsi_identity_v1');identity=loadIdentity();saveIdentity();rebuild();identityModal()}}}

